pub fn campsites_purpose() -> &'static str {
    "Campsite pads for tent, RV, cabin, group, hike-in, and yurt inventory managed across loops, ridges, and lake zones."
}

pub fn campsites_summary() -> String {
    let campsites = campsite_pads();
    let shard_total: u32 = campsites.iter().map(|item| item.shard).sum();
    let record_total: u32 = campsites.iter().map(|item| item.survey).sum();
    let pressure_total: u32 = campsites.iter().map(|item| item.pressure).sum();
    format!("campsites count={} shard={} rec={} pressure={}", campsites.len(), shard_total, record_total, pressure_total)
}

pub fn campsites_family_window(family: &str, limit: usize) -> Vec<CampsitePad> {
    campsite_pads().into_iter().filter(|item| item.family == family).take(limit).collect()
}

pub fn campsites_weighted_total(seed: u32) -> u64 {
    campsite_pads().into_iter().enumerate().map(|(index, item)| {
        let bias = (seed as u64 + index as u64 % 31) + 1;
        bias * (item.shard as u64 + item.survey as u64 * 3 + item.pressure as u64 * 5)
    }).sum()
}

pub fn campsites_nearest(shard: u32, survey: u32) -> Option<CampsitePad> {
    campsite_pads().into_iter().min_by_key(|item| {
        let a = item.shard.abs_diff(shard) as u64;
        let b = item.survey.abs_diff(survey) as u64;
        a * 7 + b * 3 + item.pressure as u64
    })
}

pub fn campsites_note_digest(limit: usize) -> Vec<String> {
    campsite_pads().into_iter().take(limit).map(|item| format!("{}:{}:{}", item.key, item.family, item.note)).collect()
}
